async function api(p,method='GET',body){let r;try{r=await fetch('/api'+p,{method,headers:body?{'Content-Type':'application/json','X-SP':'1'}:{'X-SP':'1'},body:body?JSON.stringify(body):undefined})}catch{throw Object.assign(new Error('No internet connection. Please check your network.'),{net:1})}
 const d=await r.json().catch(()=>({}));if(r.status===401&&me&&p!=='/login'){me=null;boot()}if(!r.ok)throw new Error(d.error||'Something went wrong');return d}
function toast(m,err){const t=document.createElement('div');t.className='toast'+(err?' err':'');t.textContent=m;$('#toasts').append(t);setTimeout(()=>t.remove(),err?5000:3000)}
const run=async(f)=>{try{return await f()}catch(e){toast(e.message,1)}};
const badge=s=>`<span class="badge ${s}">${s}</span>`;
const avatar=(u,c='')=>u.photo?`<img class="av ${c}" src="${u.photo}" alt="">`:`<div class="av ${c}">${esc(u.name[0])}</div>`;
const table=(cols,rows,empty='Nothing here yet')=>rows.length?`<div class="tw"><table><thead><tr>${cols.map(c=>`<th>${c[0]}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td data-l="${esc(c[0])}">${c[1](r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="empty">${empty}</div>`;
const who=u=>`<div class="pp">${avatar(u)}<div><b>${esc(u.name)}</b>${u.code?`<small>${esc(u.code)}</small>`:u.email?`<small>${esc(u.email)}</small>`:''}</div></div>`;
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b)return;const a=b.dataset.act;if(a==='close'||e.target===b&&b.classList.contains('ov')){const o=$$('.ov');o.pop()?.remove();return}(H[a]||(()=>{}))(b.dataset,b,e)});
function modal(title,body,wide,cls){const m=document.createElement('div');m.className='ov'+(cls?' '+cls:'');if(cls==='drawer')m.dataset.act='ovclose';m.innerHTML=`<div class="modal ${wide?'wide':''}"><div class="mh"><h3>${esc(title)}</h3><button class="x" data-act="close" aria-label="Close">×</button></div><div class="mb">${body}</div></div>`;document.body.append(m);return m}
const closeAll=()=>$$('.ov').forEach(o=>o.remove());
function field(f,v){const val=v[f.k]??'';const r=f.req?' required':'';
 if(f.t==='select')return`<label>${f.l}<select name="${f.k}"${r}>${f.opts.map(([a,b])=>`<option value="${a}"${String(a)===String(val)?' selected':''}>${esc(b)}</option>`).join('')}</select></label>`;
 if(f.t==='multi'){const sel=String(val).split(',');return`<label>${f.l}</label><div class="chk" style="margin:-6px 0 14px">${f.opts.map(([a,b])=>`<label><input type="checkbox" name="${f.k}" value="${a}"${sel.includes(String(a))?' checked':''}>${esc(b)}</label>`).join('')||'<span class="mu">Add a course first</span>'}</div>`}
 if(f.t==='photo')return`<label>${f.l}<input type="file" accept="image/*" data-photo><input type="hidden" name="photo" value="${esc(val)}"></label>`;
 return`<label>${f.l}<input name="${f.k}" type="${f.t||'text'}" value="${esc(val)}"${r}${f.t==='number'?' min="0"':''}${f.t==='password'?' minlength="8" autocomplete="new-password"':''}></label>`}
function form(title,fields,v,save,label='Save changes'){const m=modal(title,`<form novalidate>${fields.map(f=>field(f,v)).join('')}<div class="bar" style="margin:6px 0 0;justify-content:flex-end"><button type="button" class="btn sec" data-act="close">Cancel</button><button class="btn">${label}</button></div></form>`);
 const f=$('form',m);$('[data-photo]',m)?.addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;const img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=c.height=160;const x=c.getContext('2d'),s=Math.min(img.width,img.height);x.drawImage(img,(img.width-s)/2,(img.height-s)/2,s,s,0,0,160,160);$('[name=photo]',m).value=c.toDataURL('image/jpeg',.8)};const fr=new FileReader();fr.onload=()=>{img.src=fr.result};fr.onerror=()=>img.onerror&&img.onerror();fr.readAsDataURL(file)});
 f.onsubmit=async e=>{e.preventDefault();if(!f.checkValidity())return f.reportValidity();const o={};for(const k of new Set([...new FormData(f).keys()])){const all=new FormData(f).getAll(k);o[k]=fields.find(x=>x.k===k)?.t==='multi'?all:all[0]}
  fields.filter(x=>x.t==='multi').forEach(x=>o[x.k]=o[x.k]||[]);await run(async()=>{await save(o);m.remove()})}}
const secret=(name,email,pw)=>modal('Account created',`<p><b>${esc(name)}</b> can sign in with:</p><div class="kv"><div><small>Email</small>${esc(email)}</div><div><small>Temporary password</small><b>${esc(pw)}</b></div></div><p class="mu" style="margin-top:14px">Share this password privately. It is shown only once.</p>`);
const confirmDel=(msg,fn)=>{const m=modal('Please confirm',`<p>${msg}</p><div class="bar" style="margin:18px 0 0;justify-content:flex-end"><button class="btn sec" data-act="close">Cancel</button><button class="btn red" id="yes">Delete</button></div>`);$('#yes',m).onclick=()=>run(async()=>{await fn();m.remove()})};

