function theme(){const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;localStorage.setItem('sp-theme',t)}
const themeBtn=()=>`<button class="ic" data-act="theme" title="Switch dark / light mode" aria-label="Switch theme"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/></svg></button>`;
H.theme=theme;
let pubCourses=[],pubCfg={teacherSignup:true};
const myRole=()=>{try{return localStorage.getItem('sp-role')}catch{return null}},rememberRole=r=>{try{localStorage.setItem('sp-role',r)}catch{}};
const loginHTML=r=>`<form novalidate><label>Email<input name="email" type="email" required autocomplete="username"></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button class="btn" style="width:100%">Login as ${r}</button></form>`;
const suForm=(role,c)=>`<form novalidate><label>Full name<input name="name" required></label><label>Phone number<input name="phone" type="tel" required></label><label>Email address<input name="email" type="email" required autocomplete="username"></label>${role==='student'?`<label>Course<select name="course_id" required><option value="">Select a course</option>${pubCourses.map(x=>`<option value="${x.id}"${x.id==c?' selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`:''}<label>Password (8+ characters)<input name="password" type="password" required minlength="8" autocomplete="new-password"></label><label>Confirm password<input name="password2" type="password" required autocomplete="new-password"></label><button class="btn" style="width:100%">Send ${role} application</button></form>`;
H.m2=d=>{$$('.ov').pop()?.remove();H.m(d)};
H.sw=d=>{try{localStorage.removeItem('sp-role')}catch{}$$('.ov').pop()?.remove();H.m({k:d.k})};
H.m=d=>{const k=d.k,login=k==='login';let r=d.r||myRole();if(r==='teacher'&&!login&&!pubCfg.teacherSignup)r=null;
 if(!r){if(!login&&!pubCfg.teacherSignup)r='student';else return void modal(login?'Login':'New application',`<p class="mu" style="margin-bottom:14px">Are you a student or a teacher?</p><div class="setl"><button class="btn" data-act="m2" data-k="${k}" data-r="student" data-c="${d.c||''}">Student</button><button class="btn sec" data-act="m2" data-k="${k}" data-r="teacher">Teacher</button></div>${login?'<p class="mu" style="margin-top:14px;font-size:13px">Admin? Choose Teacher.</p>':''}`)}
 const mine=myRole()===r,m=modal(login?`Login as ${r}`:`${r==='teacher'?'Teacher':'Student'} application`,(login?loginHTML(r):suForm(r,d.c))+(mine?`<p style="margin-top:14px;text-align:center"><a class="mu" data-act="sw" data-k="${k}" style="cursor:pointer;text-decoration:underline">I am not a ${r}</a></p>`:''));
 const f=$('form',m);f.onsubmit=e=>{e.preventDefault();if(!f.checkValidity())return f.reportValidity();const o=Object.fromEntries(new FormData(f));if(!login&&o.password!==o.password2)return toast('The two passwords do not match',1);
  run(async()=>{if(login){await api('/login','POST',{...o,as:r});rememberRole(r);closeAll();boot()}else{delete o.password2;await api('/signup','POST',{...o,role:r});rememberRole(r);$('.mb',m).innerHTML=`<div class="big"><div class="t">✓</div><h3>Application sent</h3><p>The institute will review your application${r==='teacher'?' and assign your courses':''}. After approval you can login with your email and password.</p><button class="btn sec" data-act="close">Close</button></div>`}})}};
H.sc=d=>document.getElementById(d.t)?.scrollIntoView({behavior:'smooth'});
async function pub(){[pubCourses,pubCfg]=await Promise.all([api('/public/courses'),api('/public/config')]);
 $('#app').innerHTML=`<header class="nv"><div class="b2">${LOGO(40)}<span>Skill Point Institute</span></div><nav><a data-act="sc" data-t="courses">Courses</a><a data-act="sc" data-t="how">How to apply</a></nav><span class="nvt">${themeBtn()}</span><button class="btn sm sec" data-act="m" data-k="login">Login</button><button class="btn sm" data-act="m" data-k="signup">New application</button></header>
 <section class="h2"><div><span class="eyebrow">Admissions open</span><h1>Learn a skill.<br><em>Build a career.</em></h1><p>Skill Point Institute: practical courses, caring teachers, and a simple portal to follow your attendance and fees.</p><div class="bar"><button class="btn lg" data-act="m" data-k="signup">New application</button><button class="btn lg sec" data-act="m" data-k="login">Login</button></div></div><div class="orb"><i></i>${LOGO(210)}</div></section>
 <div class="fs"><div><b>Classes Monday to Saturday</b><small>Sunday is the weekly holiday</small></div><div><b>Your own portal</b><small>Attendance, courses and fees in one place</small></div><div><b>Apply in one minute</b><small>For students and teachers</small></div></div>
 <section class="sec2" id="courses"><h2>Our courses</h2><p>Pick the course that fits your goal.</p><div class="cg">${pubCourses.map(c=>`<div class="card cc"><h3>${esc(c.name)}</h3><p>Join this course and learn with our teachers.</p><button class="btn sm" data-act="m" data-k="signup" data-r="student" data-c="${c.id}">Apply</button></div>`).join('')||'<div class="card empty">Courses will be listed here soon.</div>'}</div></section>
 <section class="sec2" id="how"><h2>How admission works</h2><p>Three simple steps.</p><div class="cg">${[['Fill the form','Name, phone, email and the course you want.'],['We review it','Our team checks your application and contacts you.'],['Start learning','Get your student login and join your class.']].map((s,i)=>`<div class="card stp"><b>${i+1}</b><h3>${s[0]}</h3><p>${s[1]}</p></div>`).join('')}</div></section>
 <footer class="ft"><span>© Skill Point Institute</span>${themeBtn()}</footer>`}

