const NAV={admin:[['home','Dashboard','home'],['students','Students','users'],['teachers','Teachers','users'],['courses','Courses','book'],['attendance','Attendance','check'],['fees','Fees','wallet'],['quizzes','Quizzes','quiz'],['staff','Teacher check-ins','clock'],['apps','New applications','inbox']],
 teacher:[['home','Dashboard','home'],['mystudents','My students','users'],['courses','My courses','book'],['attendance','Attendance','check'],['quizzes','Quizzes','quiz'],['checkin','Check-in history','clock']],
 student:[['home','My profile','home'],['attendance','Attendance','check'],['quizzes','Quizzes','quiz'],['fees','Fees','wallet']]};
function shell(){const nav=NAV[me.role];$('#app').innerHTML=`<div class="shell"><aside id="sb"><div class="brand">${LOGO(38)}<div>Skill Point<small>Institute</small></div></div>${nav.map(n=>`<a data-act="go" data-p="${n[0]}" id="n-${n[0]}">${ico(n[2])}${n[1]}</a>`).join('')}<div class="sp"></div><a data-act="settings">${ico('gear')}Settings</a></aside>
 <div class="main"><header><button class="ic" id="menu" data-act="menu" aria-label="Menu">☰</button><h1 id="ttl"></h1>${themeBtn()}<button class="ic" data-act="settings" title="Settings" aria-label="Settings">${ico('gear')}</button><div class="who">${avatar(me)}<span>${esc(me.name)}</span></div></header><main id="view"></main></div></div>`}
H.ovclose=(d,b,e)=>{if(e.target===b)b.remove()};
const so=f=>()=>{$$('.ov').pop()?.remove();f()};
const shrink=file=>new Promise((res,rej)=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=c.height=160;const x=c.getContext('2d'),s=Math.min(img.width,img.height);x.drawImage(img,(img.width-s)/2,(img.height-s)/2,s,s,0,0,160,160);res(c.toDataURL('image/jpeg',.8))};img.onerror=()=>rej(new Error('Could not read that image'));const fr=new FileReader();fr.onload=()=>{img.src=fr.result};fr.onerror=()=>img.onerror&&img.onerror();fr.readAsDataURL(file)});
H.settings=async()=>{let cfg=null;if(me.role==='admin')cfg=await api('/public/config').catch(()=>null);
 const m=modal('Settings',`<div class="pr" style="margin-bottom:20px">${avatar(me,'lg')}<div><b>${esc(me.name)}</b><div class="mu" style="margin-bottom:8px">${esc(me.email)}</div><label class="btn sm sec" style="display:inline-block;margin:0 6px 0 0;cursor:pointer">Change photo<input type="file" accept="image/*" id="ph" hidden></label>${me.photo?'<button class="btn sm sec" id="phx">Remove</button>':''}</div></div>${cfg?`<label class="tg"><input type="checkbox" id="tsu"${cfg.teacherSignup?' checked':''}><span>Allow teachers to sign up from the home page</span></label>`:''}<div class="setl"><button class="btn sec" data-act="sem">${ico('inbox')}Change email</button><button class="btn sec" data-act="spw">${ico('lock')}Change password</button><button class="btn red" data-act="sout">${ico('out')}Sign out</button></div>`,0,'drawer');
 const save=async photo=>{await api('/photo','POST',{photo});me=await api('/me');const w=$('.who');if(w)w.innerHTML=`${avatar(me)}<span>${esc(me.name)}</span>`;m.remove();H.settings()};
 $('#ph',m).onchange=e=>{const f=e.target.files[0];if(f)run(async()=>save(await shrink(f)))};const rx=$('#phx',m);if(rx)rx.onclick=()=>run(()=>save(null));
 const t=$('#tsu',m);if(t)t.onchange=()=>run(async()=>{await api('/settings','PUT',{teacher_signup:t.checked});toast(t.checked?'Teacher sign-up is ON':'Teacher sign-up is OFF')})};
H.sem=so(()=>H.em());H.spw=so(()=>H.pw());H.sout=so(()=>H.logout());
H.menu=()=>$('#sb').classList.toggle('open');
H.go=d=>{location.hash='/'+d.p};H.logout=()=>{const m=modal('Sign out',`<p>Are you sure you want to sign out?</p><div class="bar" style="margin:18px 0 0;justify-content:flex-end"><button class="btn sec" data-act="close">Cancel</button><button class="btn" id="so">Yes, sign out</button></div>`);$('#so',m).onclick=()=>run(async()=>{await api('/logout','POST');closeAll();me=null;boot()})};
H.em=()=>form('Change email',[{k:'password',l:'Your password',t:'password',req:1},{k:'email',l:'New email address',t:'email',req:1}],{},o=>api('/email','POST',o).then(()=>toast('Email updated. Use it the next time you sign in.')));
H.pw=()=>form('Change password',[{k:'current',l:'Current password',t:'password',req:1},{k:'next',l:'New password (8+ characters)',t:'password',req:1}],{},o=>api('/password','POST',o).then(()=>toast('Password updated')));
async function route(){const key=(location.hash.slice(2)||'home'),n=NAV[me.role].find(x=>x[0]===key)||NAV[me.role][0];$$('aside a').forEach(a=>a.classList.toggle('on',a.id==='n-'+n[0]));$('#sb').classList.remove('open');
 $('#ttl').textContent=n[1];H={...H};await run(()=>PAGES[me.role+'.'+n[0]]());}
