let cfTimer=null;
function stopConfetti(soft){clearInterval(cfTimer);cfTimer=null;$$('.cfstop').forEach(e=>e.remove());if(soft)setTimeout(()=>$$('.cf').forEach(e=>e.remove()),7000);else $$('.cf').forEach(e=>e.remove())}
const confetti=()=>{if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;stopConfetti();const w=document.createElement('div');w.className='cf';document.body.append(w);const c=['#f5a524','#14213d','#16a34a','#3b82f6','#ef4444','#a855f7'];
 const burst=k=>{for(let i=0;i<k;i++){const p=document.createElement('i');p.style.cssText=`left:${Math.random()*100}%;background:${c[i%6]};animation-duration:${3+Math.random()*3}s;animation-delay:${Math.random()*.6}s`;p.addEventListener('animationend',()=>p.remove());w.append(p)}};
 const b=document.createElement('button');b.className='btn sm sec cfstop';b.textContent='Stop celebration';b.onclick=()=>stopConfetti();document.body.append(b);
 burst(90);const end=Date.now()+62000;cfTimer=setInterval(()=>{if(Date.now()>end)return stopConfetti(true);burst(22)},900)};
H.qback=()=>route();
function showResult(r){const why={time:'Time is up, so your quiz was submitted automatically.',exits:'You left the quiz 3 times, so it was closed. You get marks for the questions you answered.'}[r.reason]||'';
 V(`<div class="card big"><div class="ring" style="--p:${r.pct}"><b>${r.pct}%</b></div><h2 style="margin:16px 0 4px">${r.passed?'Congratulations, you passed! 🎉':'Keep practising, you can do it!'}</h2>${why?`<p style="color:var(--acx);font-weight:600">${why}</p>`:''}<p>You scored <b>${r.score} out of ${r.total}</b>. Pass mark is ${r.pass}%.</p><button class="btn" data-act="qback">Back to quizzes</button></div>
 <div class="card"><h3 class="s" style="margin-top:0">Review</h3>${table([['Question',x=>esc(x.q)],['Your answer',x=>esc(x.yours??'Not answered')],['Correct answer',x=>esc(x.correct)],['',x=>x.ok?'<span class="badge Present">Correct</span>':'<span class="badge Absent">Wrong</span>']],r.review)}</div>`);if(r.passed)confetti()}
function takeQuiz(id,d){lock={hash:location.hash};document.body.classList.add('focus');
 const n=d.questions.length,ans=d.answers.slice(),dl=d.left==null?null:Date.now()+d.left*1000;let exits=d.exits,over=false,sending=false,tm=null,chain=Promise.resolve(),i=ans.every(v=>v!==null)?n-1:Math.max(0,ans.findIndex(v=>v===null));
 const post=(p,b)=>(chain=chain.then(()=>api('/quizzes/'+id+p,'POST',b),()=>api('/quizzes/'+id+p,'POST',b)));
 const unlock=()=>{over=true;clearInterval(tm);lock=null;document.body.classList.remove('focus');document.removeEventListener('visibilitychange',vis);removeEventListener('pagehide',ph);removeEventListener('beforeunload',bu)};
 const finish=r=>{unlock();showResult(r)};
 const vis=()=>{if(over)return;if(document.hidden)post('/leave').then(r=>{if(r.ended)finish(r.ended)}).catch(()=>{});
  else post('/start').then(r=>{if(r.ended)return finish(r.ended);exits=r.exits;draw();toast(`You left the quiz. Exits used: ${exits} of ${d.max}`,1)}).catch(()=>{})};
 const ph=()=>{if(!over)fetch('/api/quizzes/'+id+'/leave',{method:'POST',keepalive:true,headers:{'X-SP':'1'}})};
 const bu=e=>{if(!over){e.preventDefault();e.returnValue=''}};
 document.addEventListener('visibilitychange',vis);addEventListener('pagehide',ph);addEventListener('beforeunload',bu);
 const submit=auto=>{if(sending||over)return;if(!auto&&ans.some(v=>v===null))return toast('Please answer every question',1);sending=true;post('/submit',{answers:ans,auto}).then(finish).catch(e=>{sending=false;toast(e.message,1)})};
 const tick=()=>{if(over||!dl)return;const s=Math.max(0,Math.round((dl-Date.now())/1000)),el=$('#tm');if(el){el.textContent='⏱ '+Math.floor(s/60)+':'+String(s%60).padStart(2,'0');el.classList.toggle('low',s<=60)}if(s<=0)submit(true)};
 const leave=()=>{const m=modal('Leave the quiz?',`<p>You have used <b>${exits}</b> of ${d.max} exits. If you leave now, the timer keeps running. After ${d.max} exits the quiz ends and you only get marks for the questions you answered.</p><div class="bar" style="margin:16px 0 0;justify-content:flex-end"><button class="btn sec" data-act="close">Stay</button><button class="btn red" id="lv">Leave quiz</button></div>`);
  $('#lv',m).onclick=()=>{m.remove();post('/leave').then(r=>{if(r.ended)return finish(r.ended);unlock();route()}).catch(e=>toast(e.message,1))}};
 function draw(){const x=d.questions[i],last=i===n-1;V(`<div class="card"><div class="bar"><b>${esc(d.title)}</b><span class="sp"></span>${dl?'<span class="tmr" id="tm"></span>':''}</div><div class="bar" style="margin:0 0 10px"><span class="mu">Question ${i+1} of ${n}</span><span class="sp"></span><span class="mu">Exits used: ${exits} of ${d.max}</span><button class="btn sm sec" id="lq">Exit quiz</button></div><div class="prog"><i style="width:${(i+1)/n*100}%"></i></div><h3 style="font-size:20px;margin:18px 0">${esc(x.q)}</h3>${x.opts.map((o,k)=>`<label class="opt${ans[i]===k?' on':''}"><input type="radio" name="o" value="${k}"${ans[i]===k?' checked':''}>${esc(o)}</label>`).join('')}<div class="bar" style="margin:18px 0 0"><button class="btn sec" id="pv"${i?'':' disabled'}>Back</button><span class="sp"></span>${last?'<button class="btn ok" id="qsub">Submit quiz</button>':'<button class="btn" id="nx">Next</button>'}</div></div>`);
  const at=i;$$('input[name=o]').forEach(r=>r.onchange=()=>{ans[at]=+r.value;$$('.opt').forEach((l,k)=>l.classList.toggle('on',k===ans[at]));post('/answer',{i:at,v:ans[at]}).then(z=>{if(z.ended)finish(z.ended)}).catch(()=>{})});
  $('#pv').onclick=()=>{i--;draw()};$('#lq').onclick=leave;const nx=$('#nx');if(nx)nx.onclick=()=>{if(ans[i]===null)return toast('Choose an answer first',1);i++;draw()};const sb=$('#qsub');if(sb)sb.onclick=()=>submit(false);tick()}
 if(dl)tm=setInterval(tick,1000);draw()}
async function studentQuizzes(){const rows=await api('/quizzes');const dur=r=>r.duration?r.duration+' min':'No time limit',gone=r=>r.expires_at&&Date.parse(r.expires_at)<Date.now(),when=r=>new Date(r.expires_at).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'});
 V(`<p class="sub">Quizzes your teacher has sent to you. You can attempt each quiz once.</p><div class="cg">${rows.map(r=>`<div class="card cc"><h3>${esc(r.title)}</h3><p>${Math.min(r.per_student,r.pool)} questions · ${dur(r)} · pass mark ${r.pass_pct}% · ${esc(r.teacher||'your teacher')}</p>${r.submitted_at?`<p>${badge(r.passed?'Pass':'Fail')} <b>${r.score}/${r.total}</b> ${r.reason==='time'?'<small class="mu">time up</small>':r.reason==='exits'?'<small class="mu">closed after 3 exits</small>':''}</p><button class="btn sm sec" data-act="qresult" data-id="${r.id}">View result</button>`:r.started_at?`<p class="mu">Exits used: ${r.exits||0} of 3</p><button class="btn sm" data-act="qgo" data-id="${r.id}">Continue</button>`:gone(r)?`<p>${badge('Expired')} <small class="mu">You did not take this quiz in time.</small></p>`:`${r.expires_at?`<p class="mu">Available until ${when(r)}</p>`:''}<button class="btn sm" data-act="qstart" data-id="${r.id}">Start quiz</button>`}</div>`).join('')||'<div class="card empty">No quizzes yet.</div>'}</div>`);
 const go=id=>run(async()=>{const d=await api('/quizzes/'+id+'/start','POST');if(d.ended)return showResult(d.ended);takeQuiz(id,d)});
 H.qgo=x=>go(x.id);H.qresult=x=>run(async()=>showResult(await api('/quizzes/'+x.id+'/result')));
 H.qstart=x=>{const r=rows.find(v=>v.id==x.id),m=modal('Before you start',`<ul class="rules"><li>${r.duration?`You have <b>${r.duration} minutes</b>. The timer keeps running even if you leave.`:'This quiz has no time limit.'}</li><li>Pass mark: <b>${r.pass_pct}%</b>.</li><li>Stay on the quiz page. Switching tabs or apps, or closing the page, counts as an <b>exit</b>.</li><li>You can exit only <b>3 times</b>. After the 3rd exit the quiz ends and you get marks for what you answered.</li><li>When time ends, your quiz is submitted automatically.</li><li>You can attempt this quiz only once.</li></ul><div class="bar" style="margin:16px 0 0;justify-content:flex-end"><button class="btn sec" data-act="close">Cancel</button><button class="btn" id="go">Start now</button></div>`);$('#go',m).onclick=()=>{m.remove();go(x.id)}}}
async function quizzesPage(){const load=async()=>{$('#tbl').innerHTML=table([['Quiz',r=>`<b>${esc(r.title)}</b>${me.role==='admin'?`<small class="mu" style="display:block">by ${esc(r.teacher||'—')}</small>`:''}`],['Questions',r=>`${Math.min(r.per_student,r.pool)} per student (pool of ${r.pool})`],['Time',r=>r.duration?r.duration+' min':'No limit'],['Pass mark',r=>r.pass_pct+'%'],['Sent to',r=>r.assigned],['Completed',r=>r.done],['',r=>`<div class="acts"><button class="btn sm" data-act="qsend" data-id="${r.id}">Send</button><button class="btn sm sec" data-act="qres" data-id="${r.id}">Results</button><button class="btn sm sec" data-act="qedit" data-id="${r.id}">Edit</button><button class="btn sm red" data-act="qdel" data-id="${r.id}">Delete</button></div>`]],await api('/quizzes'),'No quizzes yet')};
 V(`<div class="bar"><span class="mu">Create a quiz once, keep it saved, and send it to your students whenever you want. Every student gets a different random set of questions.</span><span class="sp"></span><button class="btn" data-act="qnew">Create quiz</button></div><div class="card" id="tbl"></div>`);
 H.qdel=x=>confirmDel('Delete this quiz and all its results?',()=>api('/quizzes/'+x.id,'DELETE').then(load));
 H.qreset=x=>run(async()=>{$$('.ov').pop()?.remove();sendForm(await api('/quizzes/'+x.q),+x.s)});
 H.qres=x=>run(async()=>{const z=await api('/quizzes/'+x.id),st=r=>r.submitted_at?'Completed'+(r.reason==='time'?' (time up)':r.reason==='exits'?' (3 exits)':''):r.started_at?'In progress':(r.expires_at&&Date.parse(r.expires_at)<Date.now()?'Expired (not taken)':'Not started');
  modal('Results: '+z.title,`${table([['Student',who],['Status',r=>st(r)],['Score',r=>r.submitted_at?`${r.score}/${r.total} (${Math.round(r.score*100/r.total)}%)`:'—'],['Result',r=>r.submitted_at?badge(r.passed?'Pass':'Fail'):''],['Exits',r=>r.started_at?(r.exits||0):'—'],['Deadline',r=>r.expires_at?(Date.parse(r.expires_at)<Date.now()?'Expired':new Date(r.expires_at).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'})):'No deadline'],['',r=>r.submitted_at||(!r.started_at&&r.expires_at&&Date.parse(r.expires_at)<Date.now())?`<button class="btn sm sec" data-act="qreset" data-q="${z.id}" data-s="${r.id}">Send again</button>`:'']],z.students)}<h3 class="s">Questions and correct answers</h3>${z.questions.map((x,i)=>`<p><b>${i+1}. ${esc(x.q)}</b><br>${x.opts.map((o,k)=>k===x.answer?`<span class="Present">✓ ${esc(o)}</span>`:esc(o)).join(' · ')}</p>`).join('')}`,1)});
 const unitRow=`<div style="display:flex;gap:8px;margin-top:5px"><input name="n" type="number" min="0" value="2" style="flex:1"><select name="u" style="flex:1"><option value="1">Minutes</option><option value="60" selected>Hours</option><option value="1440">Days</option></select></div><small class="mu">Example: 2 Hours means students must start the quiz within 2 hours after you send it. Type 0 for no deadline.</small>`;
 const mins=m=>Math.max(0,+$('[name=n]',m).value||0)*+$('[name=u]',m).value;
 const sendForm=async(z,pre)=>{const studs=await api('/students');if(!studs.length)return toast('No students available yet',1);const by=new Map(z.students.map(s=>[s.id,s]));
  const tag=s=>{const t=by.get(s.id);return !t?'Not sent':t.submitted_at?'Completed':t.started_at?'In progress':(t.expires_at&&Date.parse(t.expires_at)<Date.now()?'Expired':'Sent')};
  const m=modal('Send quiz: '+z.title,`<form novalidate><p class="mu" style="margin-bottom:12px">Choose the students who should get this quiz. Sending it again to a student who finished it or missed it gives them a fresh attempt.</p><div class="bar" style="margin:0 0 8px"><button type="button" class="btn sm sec" id="sa">Select all</button></div><div class="chk" style="margin-bottom:16px">${studs.map(s=>{const t=tag(s);return`<label><input type="checkbox" name="stu" value="${s.id}"${t==='In progress'?' disabled':''}${pre===s.id?' checked':''}>${esc(s.name)} <small class="mu">${t}</small></label>`}).join('')}</div><label>Quiz stays open for${unitRow}</label><div class="bar" style="margin:16px 0 0;justify-content:flex-end"><button type="button" class="btn sec" data-act="close">Cancel</button><button class="btn">Send quiz</button></div></form>`);
  $('#sa',m).onclick=()=>$$('input[name=stu]:not(:disabled)',m).forEach(i=>i.checked=true);
  $('form',m).onsubmit=e=>{e.preventDefault();const ids=$$('input[name=stu]:checked',m).map(i=>+i.value);if(!ids.length)return toast('Select at least one student',1);run(async()=>{const r=await api(`/quizzes/${z.id}/send`,'POST',{student_ids:ids,expires_minutes:mins(m)});m.remove();toast(`Quiz sent to ${r.sent} student${r.sent===1?'':'s'}${r.skipped?`, ${r.skipped} skipped (quiz in progress)`:''}`);load()})}};
 H.qsend=x=>run(async()=>sendForm(await api('/quizzes/'+x.id)));
 const quizForm=async z=>{const edit=!!z,locked=edit&&z.students.some(s=>s.started_at);let studs=[];if(!edit)studs=await api('/students');let n=0;
  const blk=x=>{const k=n++;x=x||{q:'',opts:['','','',''],answer:0};return`<div class="qb card" style="padding:14px;margin-bottom:12px"><div class="bar" style="margin-bottom:8px"><b>Question</b><span class="sp"></span><button type="button" class="btn sm red" data-act="qrm">Remove</button></div><input class="qt" placeholder="Type the question" value="${esc(x.q)}">${[0,1,2,3].map(i=>`<div class="qo"><input type="radio" name="c${k}" value="${i}"${i===x.answer?' checked':''} title="Correct answer"><input class="qv" placeholder="Option ${'ABCD'[i]}${i<2?'':' (optional)'}" value="${esc(x.opts[i]||'')}"></div>`).join('')}<small class="mu">Select the circle next to the correct answer.</small></div>`};
  const m=modal(edit?'Edit quiz':'Create quiz',`<form novalidate><label>Quiz title<input name="title" maxlength="100" value="${esc(edit?z.title:'')}"></label><label>Questions per student<input name="per" type="number" min="1" value="${edit?z.per_student:10}"></label><label>Time to finish the quiz (minutes, 0 = no time limit)<input name="dur" type="number" min="0" max="300" value="${edit?z.duration||0:0}"></label><label>Pass mark (%)<input name="pass" type="number" min="1" max="100" value="${edit?z.pass_pct||60:60}"></label>
  <label>Questions</label>${locked?`<p class="mu">Students have already started this quiz, so the questions cannot be changed. You can still change the time and pass mark. To change the questions, create a new quiz.</p>${z.questions.map((x,i)=>`<p><b>${i+1}. ${esc(x.q)}</b><br>${x.opts.map((o,k)=>k===x.answer?`<span class="Present">✓ ${esc(o)}</span>`:esc(o)).join(' · ')}</p>`).join('')}`:`<div id="qb">${(edit?z.questions:[null]).map(x=>blk(x)).join('')}</div><button type="button" class="btn sec sm" id="qadd">+ Add question</button>`}
  ${edit?'':`<h3 class="s">Send it now? (optional)</h3><p class="mu" style="margin-bottom:10px">You can just save the quiz and send it later with the Send button on the Quizzes page.</p>${studs.length?`<div class="bar" style="margin:0 0 8px"><button type="button" class="btn sm sec" id="qall">Select all</button></div><div class="chk" style="margin-bottom:14px">${studs.map(s=>`<label><input type="checkbox" name="stu" value="${s.id}">${esc(s.name)}</label>`).join('')}</div><label>Quiz stays open for${unitRow}</label>`:'<p class="mu">You have no students yet.</p>'}`}
  <div class="bar" style="margin:16px 0 0;justify-content:flex-end"><button type="button" class="btn sec" data-act="close">Cancel</button><button class="btn">${edit?'Save changes':'Save quiz'}</button></div></form>`,1);
  if(!locked)$('#qadd',m).onclick=()=>$('#qb',m).insertAdjacentHTML('beforeend',blk());const qa=$('#qall',m);if(qa)qa.onclick=()=>$$('input[name=stu]',m).forEach(i=>i.checked=true);
  $('form',m).onsubmit=e=>{e.preventDefault();const body={title:$('[name=title]',m).value,per_student:$('[name=per]',m).value,duration:$('[name=dur]',m).value,pass_pct:$('[name=pass]',m).value};
   if(!locked)body.questions=$$('.qb',m).map(b=>({q:$('.qt',b).value,opts:$$('.qv',b).map(i=>i.value),answer:+($('input[type=radio]:checked',b)?.value??0)})).filter(x=>x.q.trim()||x.opts.some(o=>o.trim()));
   if(!edit){body.student_ids=$$('input[name=stu]:checked',m).map(i=>+i.value);if(body.student_ids.length)body.expires_minutes=mins(m)}
   run(async()=>{await api(edit?'/quizzes/'+z.id:'/quizzes',edit?'PUT':'POST',body);m.remove();toast(edit?'Quiz updated':body.student_ids.length?'Quiz saved and sent to the selected students':'Quiz saved. Use Send when you want to give it to students.');load()})}};
 H.qnew=()=>run(()=>quizForm(null));H.qedit=x=>run(async()=>quizForm(await api('/quizzes/'+x.id)));
 H.qrm=(d,b)=>{const el=b.closest('.qb');if($$('.qb').length>1)el.remove();else toast('A quiz needs at least one question',1)};load()}
async function attendancePage(){const courses=await api('/courses');if(!courses.length)return V('<div class="card empty">No courses available yet.</div>');let rows=[];
 V(`<div class="bar"><label style="margin:0">Course <select id="c" style="width:auto">${courses.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label style="margin:0">Date <input type="date" id="d" value="${todayStr()}" max="${todayStr()}" style="width:auto"${me.role==='teacher'?' disabled':''}></label></div><div class="card" id="tbl"></div>`);
 const load=async()=>{if(new Date($('#d').value+'T00:00:00').getDay()===0){$('#tbl').innerHTML='<div class="empty">Sunday is the weekly holiday. Attendance is not taken.</div>';return}rows=await api(`/roster?course=${$('#c').value}&date=${$('#d').value}`);$('#tbl').innerHTML=rows.length?`<p class="mu" style="margin-bottom:12px">Mark attendance before 10 PM. Students not marked by then are recorded as Absent automatically. Once saved, only the admin can change attendance.</p>${table([['Student',who],['Status',r=>`<div class="seg">${[['Present','p'],['Absent','a'],['Leave','l']].map(([s,c])=>`<label><input type="radio" name="s${r.id}" value="${s}"${(r.status||'Absent')===s?' checked':''}${me.role==='teacher'&&r.status?' disabled':''}><span class="${c}">${s}</span></label>`).join('')}</div>${me.role==='teacher'&&r.status?'<small class="mu">Saved. Only the admin can edit.</small>':''}`]],rows)}<div class="bar" style="margin:16px 0 0;justify-content:flex-end"><button class="btn" data-act="save">Save attendance</button></div>`:'<div class="empty">No students enrolled in this course</div>'};
 $('#c').onchange=$('#d').onchange=load;H.save=()=>run(async()=>{if(!$('#d').value)throw new Error('Choose a date');await api('/attendance','POST',{course_id:$('#c').value,date:$('#d').value,records:rows.map(r=>({student_id:r.id,status:$(`input[name=s${r.id}]:checked`).value}))});toast('Attendance saved')});load()}

// ---------- boot
window.addEventListener('hashchange',()=>{if(lock){if(location.hash!==lock.hash)location.hash=lock.hash;return}me&&route()});
const LOADER='<img class="lg-img" src="/logo.png" width="96" height="96" alt="Skill Point Institute"><b>Skill Point Institute</b><i></i><span id="lmsg"></span>';
function offline(){let l=$('#loader');if(!l){l=document.createElement('div');l.id='loader';l.innerHTML=LOADER;document.body.append(l)}l.classList.remove('off');$('#lmsg').textContent='No internet connection. Reconnecting…';clearTimeout(window._rt);window._rt=setTimeout(boot,4000)}
addEventListener('online',()=>boot());
async function boot(){clearTimeout(window._rt);
 try{me=await api('/me');shell();await route()}catch(e){if(e.net)return offline();me=null;try{await pub()}catch(e2){if(e2.net)return offline()}}
 const l=$('#loader');if(l){l.classList.add('off');setTimeout(()=>l.remove(),400)}}
boot();
if('serviceWorker' in navigator)addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
